  "check_code": "from pathlib import Path\nimport sqlite3\nimport hashlib\nimport json\n\n\ndef _db_path(ws):\n    return Path(ws).resolve().parent / \"system\" / \"sailpoint_identityiq\" / \"state.db\"\n\n\ndef _rows(path):\n    con = sqlite3.connect(f\"file:{path}?mode=ro\", uri=True)\n    con.row_factory = sqlite3.Row\n    try:\n        return [dict(r) for r in con.execute(\"SELECT * FROM access_entitlement ORDER BY entitlement_id\")]\n    finally:\n        con.close()\n\n\ndef check_target_sessions(ws):\n    targets = {\"ENT-2016-00417\", \"ENT-2016-00503\"}\n    rows = {r[\"entitlement_id\"]: r for r in _rows(_db_path(ws))}\n    if set(rows) & targets != targets:\n        return {\"score\": 0, \"detail\": \"目标授权记录不完整\"}\n    bad = []\n    for entitlement_id in sorted(targets):\n        row = rows[entitlement_id]\n        if row[\"authorization_status\"] != \"revoked\" or row[\"active_session_flag\"] != 0:\n            bad.append({\"entitlement_id\": entitlement_id, \"authorization_status\": row[\"authorization_status\"], \"active_session_flag\": row[\"active_session_flag\"]})\n    if bad:\n        return {\"score\": 0, \"detail\": f\"目标后态不符: {bad}\"}\n    return {\"score\": 1, \"detail\": \"两条目标授权均保持 revoked 且 active_session_flag=0\"}\n\n\ndef check_non_target_preserved(ws):\n    targets = {\"ENT-2016-00417\", \"ENT-2016-00503\"}\n    rows = _rows(_db_path(ws))\n    normalized = []\n    for row in rows:\n        if row[\"entitlement_id\"] in targets:\n            row = {k: v for k, v in row.items() if k != \"active_session_flag\"}\n        normalized.append(row)\n    digest = hashlib.sha256(json.dumps(normalized, sort_keys=True, separators=(\",\", \":\")).encode()).hexdigest()\n    if digest != \"06f8ea15262b5be3295bf713a73b44e520260bb01633635719aaaa6e09aafa7f\":\n        return {\"score\": 0, \"detail\": \"发现目标以外授权或目标其他字段发生变更\"}\n    if len(rows) != 84:\n        return {\"score\": 0, \"detail\": \"授权记录数量发生变化\"}\n    return {\"score\": 1, \"detail\": \"除两条目标 active_session_flag 从1到0外无授权表变更\"}\n",
